#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Non-secret facts only. Secrets go to your password manager, never here.
# Kept under the workspace, not $HOME: the dev container is rebuilt and loses ~/.
# Override with SMH_FACTS_FILE=... if the workspace lives elsewhere.
ENV_FILE="${SMH_FACTS_FILE:-/workspaces/audiobook-ai-docker-image/myProjects/skillWizardRun/smh-platform-facts.env}"
mkdir -p "$(dirname "$ENV_FILE")"
TOTAL_STAGES=9

banner "Google / YouTube setup for Social Media Harvester"

stage "Ground rule: where secrets go"
warn "This wizard NEVER asks for a secret. Do not paste one into it."
say "Secrets (client secret, API key) go ONLY into your password manager."
say "Non-secret facts (project id, client id, test results) are saved to:"
note "  $ENV_FILE"
pause "Password manager open and ready?"

stage "Create the Google Cloud project"
note "YouTube allows only ONE API project per client: reuse it for everything."
open_url "https://console.cloud.google.com/projectcreate"
step "Name it e.g. 'social-media-harvester' and click Create."
step "Copy the Project ID (shown under the name; may differ from the name)."
ask GCP_PROJECT_ID "Project ID:"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"

stage "Enable the two YouTube APIs"
open_url "https://console.cloud.google.com/apis/library/youtube.googleapis.com?project=$GCP_PROJECT_ID"
step "Click Enable on 'YouTube Data API v3'."
pause "Done? Press Enter to open the next API."
open_url "https://console.cloud.google.com/apis/library/youtubeanalytics.googleapis.com?project=$GCP_PROJECT_ID"
step "Click Enable on 'YouTube Analytics API'."
pause "Both enabled?"

stage "OAuth consent (Google Auth Platform)"
note "If the console looks different, find 'Google Auth Platform' / 'OAuth consent screen'."
open_url "https://console.cloud.google.com/auth/overview?project=$GCP_PROJECT_ID"
step "Get started → App name 'Social Media Harvester', support email = yours."
step "Audience: External. Contact email = yours. Finish / Create."
pause "Done? Press Enter for scopes."
open_url "https://console.cloud.google.com/auth/scopes?project=$GCP_PROJECT_ID"
step "Add or remove scopes → add these two, then Save:"
note "  https://www.googleapis.com/auth/youtube.readonly"
note "  https://www.googleapis.com/auth/yt-analytics.readonly"
pause "Done? Press Enter for publishing status."
open_url "https://console.cloud.google.com/auth/audience?project=$GCP_PROJECT_ID"
step "Click 'Publish app' → confirm. Status should read 'In production'."
note "Unverified is fine for now (warning screen, 100-user cap). Testing mode"
note "would kill refresh tokens after 7 days."
ask GOOGLE_PUBLISHING_STATUS "Publishing status shown (e.g. In production):"
write_env GOOGLE_PUBLISHING_STATUS "$GOOGLE_PUBLISHING_STATUS"

stage "OAuth client (Web application)"
open_url "https://console.cloud.google.com/auth/clients/create?project=$GCP_PROJECT_ID"
step "Application type: Web application. Name: 'smh-local'."
step "Authorized redirect URIs → add both:"
note "  http://localhost:8080/login/oauth2/code/google"
note "  https://developers.google.com/oauthplayground"
step "Click Create."
warn "The client SECRET may be shown only once: save it to your password manager NOW."
pause "Client secret saved in password manager?"
step "Copy the Client ID (ends .apps.googleusercontent.com; it is not secret)."
ask GOOGLE_OAUTH_CLIENT_ID "Client ID:"
write_env GOOGLE_OAUTH_CLIENT_ID "$GOOGLE_OAUTH_CLIENT_ID"

stage "API key (restricted to YouTube Data API v3)"
open_url "https://console.cloud.google.com/apis/credentials?project=$GCP_PROJECT_ID"
step "Create credentials → API key."
step "Edit the key → name 'smh-youtube' → API restrictions → Restrict key →"
step "tick only 'YouTube Data API v3' → Save."
warn "Save the key to your password manager. Do NOT paste it here."
pause "API key saved and restricted?"

stage "Smoke test: API key (in your browser)"
say "Paste this into a browser tab, replacing YOUR_KEY from your password manager:"
note "  https://www.googleapis.com/youtube/v3/channels?part=contentDetails&forHandle=@NBA&key=YOUR_KEY"
step "Expect JSON with contentDetails.relatedPlaylists.uploads (starts 'UU')."
ask YT_SMOKE_API_KEY "Result (e.g. 'ok UU...' or the error message):"
write_env YT_SMOKE_API_KEY "$YT_SMOKE_API_KEY"

stage "Smoke test: OAuth as your channel (OAuth Playground)"
open_url "https://developers.google.com/oauthplayground"
step "Gear icon (top right) → tick 'Use your own OAuth credentials' →"
step "paste Client ID and Client secret (in the browser only)."
step "Step 1 box → paste both scopes (space-separated) → Authorize APIs:"
note "  https://www.googleapis.com/auth/youtube.readonly https://www.googleapis.com/auth/yt-analytics.readonly"
step "Sign in as the Google account that owns YOUR channel; accept the"
step "'unverified app' warning (Advanced → Go to ...)."
step "Step 2 → Exchange authorization code for tokens."
step "Step 3 → Request URI, GET:"
note "  https://youtubeanalytics.googleapis.com/v2/reports?ids=channel==MINE&startDate=2026-01-01&endDate=2026-11-20&metrics=views"
ask YT_CHANNEL_HANDLE "Your channel's @handle:"
write_env YT_CHANNEL_HANDLE "$YT_CHANNEL_HANDLE"
ask YT_SMOKE_OAUTH "Result (e.g. 'ok rows returned' or the error):"
write_env YT_SMOKE_OAUTH "$YT_SMOKE_OAUTH"
note "Optional: revoke the Playground's access later at myaccount.google.com/permissions."

stage "Record the quotas"
open_url "https://console.cloud.google.com/apis/api/youtube.googleapis.com/quotas?project=$GCP_PROJECT_ID"
step "Note 'Queries per day' (expect 10,000)."
ask YT_DATA_QUOTA "Data API v3 queries/day:"
write_env YT_DATA_QUOTA "$YT_DATA_QUOTA"
open_url "https://console.cloud.google.com/apis/api/youtubeanalytics.googleapis.com/quotas?project=$GCP_PROJECT_ID"
ask YT_ANALYTICS_QUOTA "Analytics API quota shown (or 'none shown'):"
write_env YT_ANALYTICS_QUOTA "$YT_ANALYTICS_QUOTA"

finish
note "Tell Claude you're done; it will read $ENV_FILE (no secrets in it)."
}

run_wizard "$@"; exit
